package fr.pikeo.logistique;
import android.app.*;import android.content.*;import android.os.Build;import androidx.core.app.NotificationCompat;import org.json.*;import java.util.*;
public class PikeoAlarmReceiver extends BroadcastReceiver {
 private static PendingIntent pending(Context c,String id,String title){Intent i=new Intent(c,PikeoAlarmReceiver.class).setAction("fr.pikeo.ALARM").putExtra("id",id).putExtra("title",title);i.setData(android.net.Uri.parse("pikeo://alarm/"+id));return PendingIntent.getBroadcast(c,id.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static boolean schedule(Context c,String id,long at,String title)throws Exception {AlarmManager a=c.getSystemService(AlarmManager.class);PendingIntent p=pending(c,id,title);boolean exact=Build.VERSION.SDK_INT<31||a.canScheduleExactAlarms();if(exact)a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,p);else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,p);JSONObject r=new JSONObject().put("at",at).put("title",title);c.getSharedPreferences("pikeo_alarms",0).edit().putString(id,r.toString()).commit();return exact;}
 public static void cancel(Context c,String id){c.getSystemService(AlarmManager.class).cancel(pending(c,id,""));c.getSharedPreferences("pikeo_alarms",0).edit().remove(id).commit();}
 public void onReceive(Context c,Intent i){WorkReminders.channels(c);if(Intent.ACTION_BOOT_COMPLETED.equals(i.getAction())||Intent.ACTION_MY_PACKAGE_REPLACED.equals(i.getAction())||Intent.ACTION_TIME_CHANGED.equals(i.getAction())||Intent.ACTION_TIMEZONE_CHANGED.equals(i.getAction())||"android.app.action.SCHEDULE_EXACT_ALARM_PERMISSION_STATE_CHANGED".equals(i.getAction())){for(Map.Entry<String,?> e:c.getSharedPreferences("pikeo_alarms",0).getAll().entrySet())try{JSONObject r=new JSONObject((String)e.getValue());long at=r.getLong("at");if(at>System.currentTimeMillis())schedule(c,e.getKey(),at,r.getString("title"));}catch(Exception ignored){}try{WorkReminders.rebuild(c);}catch(Exception ignored){}return;}
  String id=i.getStringExtra("id");if(id==null)return;c.getSharedPreferences("pikeo_alarms",0).edit().remove(id).commit();NotificationManager n=c.getSystemService(NotificationManager.class);if(Build.VERSION.SDK_INT>=26){NotificationChannel channel=new NotificationChannel("pikeo_tasks","Tâches et échéances",NotificationManager.IMPORTANCE_HIGH);channel.enableVibration(true);n.createNotificationChannel(channel);}boolean work=id.startsWith("work_")||id.equals("test_work");boolean sound=false;try{sound=WorkReminders.config(c).optBoolean("sound",false);if(id.startsWith("work_"))WorkReminders.next(c,id);}catch(Exception ignored){}String channelId=work?(sound?"pikeo_work_soft_v1":"pikeo_work_vibrate_v1"):"pikeo_tasks";Intent open=new Intent(c,MainActivity.class);PendingIntent p=PendingIntent.getActivity(c,id.hashCode(),open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);try{n.notify(id.hashCode(),new NotificationCompat.Builder(c,channelId).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle(i.getStringExtra("title")).setContentText(work?"Rappel de vos horaires de travail.":"Ouvrez Pikéo pour vérifier votre tâche.").setCategory(NotificationCompat.CATEGORY_REMINDER).setPriority(NotificationCompat.PRIORITY_HIGH).setVibrate(new long[]{0,350,180,350}).setSound(work&&sound?android.net.Uri.parse("android.resource://"+c.getPackageName()+"/raw/pikeo_soft_beep"):null).setVisibility(NotificationCompat.VISIBILITY_PRIVATE).setContentIntent(p).setAutoCancel(true).build());}catch(SecurityException ignored){}
 }
}
